import SectionHeading from "../components/SectionHeading";
import CardLink from "../components/CardLink";
import { AUDIO_SOURCES } from "../data/audioSources";

export default function AudioPage() {
  return (
    <div>
      <div className="audio-hero">
        <div className="big-icon">🎧</div>
        <h2>Islamic Audio Lectures</h2>
        <p>High-quality, authentic lectures from world-renowned scholars. Listen anytime, anywhere — completely free.</p>
      </div>

      <SectionHeading title="Lecture Platforms" tag="Authenticated Sources" />
      <div className="grid">
        {AUDIO_SOURCES.map(r => (
          <div className="card" key={r.name}>
            <div className="card-icon">{r.icon}</div>
            <h4>{r.name}</h4>
            <p>{r.desc}</p>
            <CardLink href={r.link} />
          </div>
        ))}
      </div>

      <div className="concept-box" style={{ marginTop: 32 }}>
        <h3>📅 Recommended Daily Listening</h3>
        <p>🌅 <strong>Morning:</strong> 15–20 min Quran Tafsir — Bayyinah or Yaqeen Institute</p>
        <p>🌆 <strong>Evening:</strong> Aqeedah or Seerah — EmaanLibrary or Muslim Central</p>
        <p>📆 <strong>Weekend:</strong> Full seminar — AlMaghrib or Bakkah.net</p>
        <div className="hadith-quote">"The best of you are those who learn the Quran and teach it." — Prophet Muhammad ﷺ (Sahih al-Bukhari)</div>
      </div>
    </div>
  );
}
